<script type="application/ld+json">{"@context":"https://schema.org","@graph":[{"@type":"ProfessionalService","@id":"https://pennsylvaniainsuranceappraiser.com/#business","name":"Pennsylvania Insurance Appraiser","url":"https://pennsylvaniainsuranceappraiser.com/","telephone":"+1 (844) 537-1427","email":"info@pennsylvaniainsuranceappraiser.com","logo":{"@type":"ImageObject","@id":"https://pennsylvaniainsuranceappraiser.com/#logo","url":"https://pennsylvaniainsuranceappraiser.com/favicon-512.png","contentUrl":"https://pennsylvaniainsuranceappraiser.com/favicon-512.png","width":512,"height":512,"caption":"Pennsylvania Insurance Appraiser"},"image":{"@id":"https://pennsylvaniainsuranceappraiser.com/#logo"},"address":{"@type":"PostalAddress","addressRegion":"PA","addressCountry":"US"},"contactPoint":[{"@type":"ContactPoint","telephone":"+1 (844) 537-1427","email":"info@pennsylvaniainsuranceappraiser.com","contactType":"customer service","areaServed":"US-PA","availableLanguage":"en"}],"slogan":"Independent appraisal for underpaid Pennsylvania property claims","description":"Independent insurance appraisal, estimate review and umpire services for disputed property claims across all 67 Pennsylvania counties.","areaServed":[{"@type":"State","name":"Pennsylvania"},{"@type":"City","name":"Philadelphia"},{"@type":"City","name":"Pittsburgh"},{"@type":"City","name":"Allentown"},{"@type":"City","name":"Erie"},{"@type":"City","name":"Reading"},{"@type":"City","name":"Scranton"},{"@type":"City","name":"Lancaster"},{"@type":"City","name":"Harrisburg"},{"@type":"City","name":"State College"},{"@type":"City","name":"Wilkes-Barre"},{"@type":"City","name":"York"},{"@type":"City","name":"Johnstown"}],"hasOfferCatalog":{"@type":"OfferCatalog","name":"Insurance appraisal services","itemListElement":[{"@type":"Offer","itemOffered":{"@type":"Service","name":"Appraisal Demand Representation","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/appraisal-demand-representation/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Homeowner Claim Appraisal","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/home-insurance-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial & HOA Appraisal","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/commercial-hoa-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/roof-hail-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wind & Tornado Appraisal","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/windstorm-tornado-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Tropical Storm Remnant Appraisal","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/tropical-storm-remnant-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Claim Appraisal","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/water-damage-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/fire-smoke-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Dam & Frozen Pipe Appraisal","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/ice-dam-frozen-pipe-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/insurance-estimate-audit/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire & Neutral Services","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/umpire-neutral-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Ice dam claims","Hail and wind damage","Water damage claims"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}],"priceRange":"$$"},{"@type":"WebSite","@id":"https://pennsylvaniainsuranceappraiser.com/#website","url":"https://pennsylvaniainsuranceappraiser.com/","name":"Pennsylvania Insurance Appraiser","publisher":{"@id":"https://pennsylvaniainsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://pennsylvaniainsuranceappraiser.com/claim-terms-glossary/#webpage","url":"https://pennsylvaniainsuranceappraiser.com/claim-terms-glossary/","name":"Claim Terms Glossary | ACV, RCV, Umpire & More","description":"Searchable claim terms glossary: plain-English definitions of ACV, RCV, holdback, appraisal award, umpire, mine subsidence and more.","inLanguage":"en-US","isPartOf":{"@id":"https://pennsylvaniainsuranceappraiser.com/#website"},"about":{"@id":"https://pennsylvaniainsuranceappraiser.com/#business"},"publisher":{"@id":"https://pennsylvaniainsuranceappraiser.com/#business"},"dateModified":"2026-11-14","primaryImageOfPage":{"@type":"ImageObject","@id":"https://pennsylvaniainsuranceappraiser.com/claim-terms-glossary/#primaryimage","url":"https://pennsylvaniainsuranceappraiser.com/assets/img/photos/calc-papers.webp","contentUrl":"https://pennsylvaniainsuranceappraiser.com/assets/img/photos/calc-papers.webp","width":1200,"height":749},"breadcrumb":{"@id":"https://pennsylvaniainsuranceappraiser.com/claim-terms-glossary/#breadcrumb"},"mainEntity":{"@id":"https://pennsylvaniainsuranceappraiser.com/claim-terms-glossary/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pennsylvaniainsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim terms glossary","item":"https://pennsylvaniainsuranceappraiser.com/claim-terms-glossary/"}],"@id":"https://pennsylvaniainsuranceappraiser.com/claim-terms-glossary/#breadcrumb"},{"@type":"DefinedTermSet","name":"Property insurance claim terms glossary","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. Many policies pay ACV first and the balance after repairs are done."},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for the extra cost of living elsewhere while your home is unlivable after a covered loss, often part of Coverage D."},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of a covered loss — the question an appraisal panel is normally limited to deciding."},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision signed by at least two of the three panel members that sets the amount of loss."},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy provision that lets either party demand appraisal when they disagree on the amount of a covered loss."},{"@type":"DefinedTerm","name":"Bad faith","description":"Unreasonable conduct by an insurer toward its insured. Pennsylvania’s bad-faith statute lets a court award certain remedies; appraisal does not decide it."},{"@type":"DefinedTerm","name":"Building code upgrade (ordinance or law)","description":"Coverage for extra costs needed to bring repaired work up to current building codes, often subject to its own limit."},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage for the house itself and attached structures."},{"@type":"DefinedTerm","name":"Coverage B","description":"Other structures coverage for detached garages, fences, sheds and similar buildings."},{"@type":"DefinedTerm","name":"Coverage C","description":"Personal property coverage for furniture, clothing, electronics and other belongings."},{"@type":"DefinedTerm","name":"Coverage D","description":"Loss of use coverage, including additional living expense or fair rental value."},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy showing the insured, property, coverages, limits, deductibles and policy period."},{"@type":"DefinedTerm","name":"Deductible","description":"The portion of a covered loss you pay before the insurer pays, subtracted from the claim payment."},{"@type":"DefinedTerm","name":"Depreciation","description":"A reduction in value for age, wear and condition, used to calculate actual cash value."},{"@type":"DefinedTerm","name":"Disinterested appraiser","description":"An appraiser with no financial stake in the outcome beyond a reasonable fee, as most appraisal clauses require."},{"@type":"DefinedTerm","name":"Earth movement exclusion","description":"Policy language that excludes damage from earthquakes, landslides, subsidence, sinkholes and similar ground movement, with limited exceptions."},{"@type":"DefinedTerm","name":"FAIR Plan","description":"The Pennsylvania FAIR Plan, the state’s insurer of last resort for property owners who can’t get coverage in the regular market."},{"@type":"DefinedTerm","name":"Flood exclusion","description":"Standard homeowner policy language excluding damage from surface water and rising water; flood coverage comes from NFIP or private flood policies."},{"@type":"DefinedTerm","name":"Holdback","description":"The recoverable depreciation an insurer withholds until repairs are completed and documented."},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at the roof edge that traps melting snow, which can back up under shingles and leak into the home."},{"@type":"DefinedTerm","name":"Line item","description":"A single entry in an estimate, such as a quantity of drywall or roofing, with its unit price and total."},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether undamaged materials must be replaced so repairs reasonably match in color, texture or style."},{"@type":"DefinedTerm","name":"Mine Subsidence Insurance (MSI)","description":"A program run by the Pennsylvania Department of Environmental Protection that covers damage from the collapse of underground coal mines."},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps to prevent further damage after a loss, such as tarping a roof or drying out a wet basement."},{"@type":"DefinedTerm","name":"NFIP","description":"The National Flood Insurance Program, the federal program that writes most flood insurance policies."},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s charges for overhead and profit, commonly added when a repair needs coordination of several trades."},{"@type":"DefinedTerm","name":"Party wall","description":"A shared wall between two attached homes, common in rowhomes and twins, which can complicate repair scope and responsibility."},{"@type":"DefinedTerm","name":"Pennsylvania Insurance Department","description":"The state agency, led by the Insurance Commissioner, that regulates insurers, takes consumer complaints and licenses public adjusters."},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, which some policies require within a set time after the insurer asks."},{"@type":"DefinedTerm","name":"Public adjuster","description":"A professional licensed by the Pennsylvania Insurance Department to prepare and negotiate a claim on the policyholder’s behalf for a fee."},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation that can be paid back once repairs or replacement are completed under a replacement cost policy."},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with materials of like kind and quality, without a deduction for depreciation."},{"@type":"DefinedTerm","name":"Reservation of rights","description":"A letter in which an insurer handles a claim while reserving the right to deny coverage later."},{"@type":"DefinedTerm","name":"Roof square","description":"A roofing unit equal to 100 square feet of roof surface."},{"@type":"DefinedTerm","name":"Scope of loss","description":"The full description of damaged areas and the repairs needed, separate from pricing."},{"@type":"DefinedTerm","name":"Statement of loss","description":"The insurer’s summary of the claim showing RCV, depreciation, deductible, prior payments and the net amount paid."},{"@type":"DefinedTerm","name":"Suit-limitation clause","description":"Policy language limiting the time to sue the insurer, commonly one year from the date of loss in Pennsylvania property policies."},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add items or costs to an estimate after hidden damage is found or pricing changes."},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the two appraisers can’t agree on."},{"@type":"DefinedTerm","name":"Unfair claims practices","description":"Claim-handling conduct the Unfair Insurance Practices Act and related regulations prohibit, such as failing to respond or investigate promptly."},{"@type":"DefinedTerm","name":"Wind-driven rain","description":"Rain forced into a building by wind; coverage often depends on whether the wind first created an opening."},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers, adjusters and contractors to price property repairs."}],"@id":"https://pennsylvaniainsuranceappraiser.com/claim-terms-glossary/#definedtermset"}]}</script>
</head>
